"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatCard } from "@/components/app/stat-card";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Stethoscope, CheckCircle2, Activity, AlertTriangle, MapPin, Calendar, ChevronRight, Heart } from "lucide-react";
import { formatDateTime, formatDate } from "@/lib/constants";

const STAGE_TONES: Record<string, string> = {
  "Đã hồi phục": "bg-[var(--success-bg)] text-[var(--success-fg)]",
  "Đang hồi phục": "bg-[var(--info-bg)] text-[var(--info-fg)]",
  "Theo dõi": "bg-[var(--warning-bg)] text-[var(--warning-fg)]",
  "Cần can thiệp": "bg-[var(--danger-bg)] text-[var(--danger-fg)]",
};

export function RecoveryDashboard() {
  const { navigate } = useAppStore();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    (async () => {
      try { setData(await apiGet("/recovery-dashboard")); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState variant="detail" />;
  if (error) return <ErrorState message={error} />;
  if (!data) return <ErrorState message="Không có dữ liệu" />;

  const { stats, summary, recoveries } = data;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Theo dõi hồi phục"
        description="Tình trạng hồi phục của ngựa sau vận chuyển"
        icon={<Stethoscope className="h-5 w-5" />}
      />

      {/* Stats */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Tổng ngựa theo dõi" value={stats.totalHorses} icon={<Heart className="h-6 w-6" />} tone="default" delay={0} />
        <StatCard label="Sẵn sàng thi đấu" value={stats.readyCount} icon={<CheckCircle2 className="h-6 w-6" />} tone="success" delay={0.05} />
        <StatCard label="Đang hồi phục" value={stats.recoveringCount} icon={<Activity className="h-6 w-6" />} tone="info" delay={0.1} />
        <StatCard label="Cần can thiệp" value={stats.needsAttentionCount} icon={<AlertTriangle className="h-6 w-6" />} tone="danger" delay={0.15} />
      </div>

      {/* Per-horse summary cards */}
      {summary.length === 0 ? (
        <EmptyState icon={<Stethoscope className="h-6 w-6" />} title="Chưa có đánh giá hồi phục" description="Sau khi chuyến vận chuyển hoàn thành và bàn giao, đánh giá hồi phục sẽ hiển thị tại đây." />
      ) : (
        <div className="grid gap-4 lg:grid-cols-2">
          {summary.map((s: any, i: number) => (
            <Card key={s.horse.horseId} className="card-hover overflow-hidden">
              <CardContent className="p-5">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-center gap-3">
                    <div className={`flex h-12 w-12 items-center justify-center rounded-xl ${s.readyToRace ? "bg-[var(--success-bg)] text-[var(--success-fg)]" : STAGE_TONES[s.latestStage] || "bg-muted text-muted-foreground"}`}>
                      <Stethoscope className="h-6 w-6" />
                    </div>
                    <div>
                      <h3 className="text-base font-bold tracking-tight">{s.horse.name}</h3>
                      <p className="text-xs text-muted-foreground">{s.horse.microchipId} · {s.horse.gender}</p>
                    </div>
                  </div>
                  {s.readyToRace && <Badge className="bg-[var(--success)] text-white gap-1"><CheckCircle2 className="h-3 w-3" /> Sẵn sàng thi đấu</Badge>}
                </div>

                <div className="mt-4 flex items-center justify-between rounded-lg border border-border p-3">
                  <div>
                    <p className="text-xs text-muted-foreground">Giai đoạn hiện tại</p>
                    <p className="text-sm font-semibold">{s.latestStage}</p>
                  </div>
                  <StatusBadge status={s.latestStage} />
                </div>

                <div className="mt-3">
                  <p className="mb-2 text-xs font-medium uppercase tracking-wider text-muted-foreground">Đánh giá gần đây ({s.assessments.length})</p>
                  <div className="space-y-2">
                    {s.assessments.slice(0, 3).map((a: any) => (
                      <button key={a.recoveryId} onClick={() => navigate("trip-detail", { id: a.planId })} className="flex w-full items-center gap-3 rounded-lg border border-border p-2.5 text-left transition-colors hover:border-primary/40">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 text-xs">
                            <span className="flex items-center gap-1 text-muted-foreground"><MapPin className="h-3 w-3" />{a.plan?.request?.origin?.name} → {a.plan?.request?.destination?.name}</span>
                          </div>
                          <p className="mt-0.5 text-xs text-muted-foreground flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDateTime(a.assessmentDate)}</p>
                        </div>
                        <div className="flex items-center gap-2 text-xs">
                          {a.stressLevel && <span>Stress <strong className={a.stressLevel >= 4 ? "text-[var(--danger-fg)]" : ""}>{a.stressLevel}/5</strong></span>}
                          {a.heartRate && <span>Nhịp <strong>{a.heartRate}</strong></span>}
                          {a.temperature && <span>Nhiệt <strong>{a.temperature}°C</strong></span>}
                        </div>
                        <ChevronRight className="h-3.5 w-3.5 text-muted-foreground" />
                      </button>
                    ))}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Recent assessments timeline */}
      {recoveries.length > 0 && (
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Activity className="h-4 w-4" /> Lịch sử đánh giá gần đây</CardTitle></CardHeader>
          <CardContent>
            <div className="relative space-y-4 before:absolute before:left-[15px] before:top-2 before:h-full before:w-0.5 before:bg-border">
              {recoveries.slice(0, 10).map((r: any) => (
                <div key={r.recoveryId} className="relative flex gap-4">
                  <div className={`z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full ring-4 ring-background ${r.readyToRace ? "bg-[var(--success)] text-white" : r.recoveryStage === "Cần can thiệp" ? "bg-[var(--danger)] text-white" : "bg-primary/10 text-primary"}`}>
                    <Stethoscope className="h-4 w-4" />
                  </div>
                  <div className="flex-1 pb-2">
                    <div className="flex items-center justify-between gap-2">
                      <p className="text-sm font-semibold">{r.horse?.name}</p>
                      <StatusBadge status={r.recoveryStage} />
                    </div>
                    <p className="text-xs text-muted-foreground">{formatDateTime(r.assessmentDate)} · {r.plan?.request?.competitionName}</p>
                    {r.vetNotes && <p className="mt-1 text-sm text-muted-foreground">{r.vetNotes}</p>}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
