"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { FileText, Plus, Search, MapPin, Calendar, Heart, ChevronRight, Download } from "lucide-react";
import { formatDate, formatMoney } from "@/lib/constants";
import { exportToCSV } from "@/lib/csv-export";
import { useToast } from "@/hooks/use-toast";
import { ListStatsBar } from "@/components/app/list-stats-bar";

// Đã chuẩn hóa danh sách filter khớp với luồng vòng đời vận chuyển
const STATUS_FILTERS = ["Tất cả", "PENDING", "APPROVED", "IN_TRANSIT", "COMPLETED", "REJECTED", "CANCELLED"];

// Helper để dịch trạng thái tiếng Anh sang tiếng Việt trên UI bộ lọc
const translateStatus = (status: string) => {
  const map: Record<string, string> = {
    "PENDING": "Chờ duyệt",
    "APPROVED": "Đã phê duyệt",
    "IN_TRANSIT": "Đang vận chuyển",
    "COMPLETED": "Hoàn thành",
    "REJECTED": "Từ chối",
    "CANCELLED": "Đã hủy",
    "Tất cả": "Tất cả"
  };
  return map[status] || status;
};

export function RequestList() {
  const { navigate } = useAppStore();
  const { toast } = useToast();
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("Tất cả");

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        // Gọi API lấy danh sách yêu cầu của user hiện tại
        const data = await apiGet("/api/transport-requests/my");
        // Kiểm tra và gán dữ liệu (fallback cho nhiều cấu trúc trả về)
        setRequests(Array.isArray(data) ? data : data.requests || data.data || []);
      } catch (e: any) { 
        setError(e.message || "Không thể tải danh sách yêu cầu."); 
      } finally { 
        setLoading(false); 
      }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = requests.filter((r) => {
    const rId = String(r.id || r.requestId || "");
    const matchSearch = !search || 
      (r.competitionName || "").toLowerCase().includes(search.toLowerCase()) || 
      rId.toLowerCase().includes(search.toLowerCase());
    
    // So sánh trạng thái (chuẩn hóa về chữ in hoa để so sánh)
    const currentStatus = (r.status || "").toUpperCase();
    const matchStatus = statusFilter === "Tất cả" || currentStatus === statusFilter;
    
    return matchSearch && matchStatus;
  });

  const handleExportCSV = () => {
    const headers = ["Mã đơn", "Cuộc thi", "Tuyến", "Ngày khởi hành", "Ngày đến", "Số ngựa", "Tổng dự kiến", "Loại tiền", "Trạng thái"];
    const rows = filtered.map((r) => {
      const rId = String(r.id || r.requestId || "");
      return [
        rId.slice(-8).toUpperCase(),
        r.competitionName || "Chưa đặt tên",
        `${r.originLocation?.name || r.origin?.name || ""} → ${r.destinationLocation?.name || r.destination?.name || ""}`,
        formatDate(r.scheduledDepartureDate),
        formatDate(r.scheduledArrivalDate),
        r.horses?.length || r.horseIds?.length || 0,
        r.estimatedAmount || 0,
        r.currency || "VND",
        translateStatus(r.status?.toUpperCase() || ""),
      ];
    });
    exportToCSV(`equideli-yeu-cau-${new Date().toISOString().slice(0, 10)}.csv`, headers, rows);
    toast({ title: "Đã xuất CSV", description: `${rows.length} yêu cầu đã được tải xuống.` });
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Yêu cầu vận chuyển"
        description="Tạo và theo dõi đơn vận chuyển ngựa đua"
        icon={<FileText className="h-5 w-5" />}
        actions={
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={handleExportCSV} disabled={filtered.length === 0} className="gap-1.5"><Download className="h-4 w-4" /> <span className="hidden sm:inline">Xuất CSV</span></Button>
            <Button onClick={() => navigate("request-create")} className="gap-2"><Plus className="h-4 w-4" /> Tạo yêu cầu</Button>
          </div>
        }
      />

      {/* Filters */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative w-full sm:w-72">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm mã đơn, tên cuộc thi..." className="pl-9" />
        </div>
        <div className="flex flex-wrap gap-1.5">
          {STATUS_FILTERS.map((s) => (
            <button key={s} onClick={() => setStatusFilter(s)} className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${statusFilter === s ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:bg-muted/70"}`}>
              {translateStatus(s)}
            </button>
          ))}
        </div>
      </div>

      {/* Stats overview */}
      <ListStatsBar
        total={requests.length}
        filtered={filtered.length}
        stats={[
          { label: "Đã phê duyệt", value: requests.filter((r) => r.status?.toUpperCase() === "APPROVED").length, tone: "success" },
          { label: "Đang chờ duyệt", value: requests.filter((r) => r.status?.toUpperCase() === "PENDING").length, tone: "warning" },
          { label: "Đang vận chuyển", value: requests.filter((r) => r.status?.toUpperCase() === "IN_TRANSIT").length, tone: "info" },
        ]}
      />

      {filtered.length === 0 ? (
        <EmptyState illustration="empty-list" title="Không tìm thấy đơn nào" description="Bạn chưa có yêu cầu vận chuyển nào ở trạng thái này." action={<Button size="sm" onClick={() => navigate("request-create")} className="gap-1"><Plus className="h-4 w-4" /> Tạo yêu cầu ngay</Button>} />
      ) : (
        <div className="space-y-3">
          {filtered.map((r) => {
            const rId = String(r.id || r.requestId || "");
            const numHorses = r.horses?.length || r.horseIds?.length || r.horseCount || 0;
            return (
              <button key={rId} onClick={() => navigate("request-detail", { id: rId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
                <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><FileText className="h-6 w-6" /></div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <p className="truncate text-sm font-semibold">{r.competitionName || `Đơn #${rId.slice(-8).toUpperCase()}`}</p>
                  </div>
                  <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{r.originLocation?.name || r.origin?.name || "Chưa rõ"} → {r.destinationLocation?.name || r.destination?.name || "Chưa rõ"}</span>
                    <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDate(r.scheduledDepartureDate)}</span>
                    <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{numHorses} ngựa</span>
                  </div>
                </div>
                <div className="flex flex-col items-end gap-1.5">
                  {/* StatusBadge nên tự động đổi màu dựa trên chuỗi PENDING, APPROVED... */}
                  <StatusBadge status={r.status || "PENDING"} />
                  {r.estimatedAmount ? <span className="text-xs font-semibold text-foreground">{formatMoney(r.estimatedAmount, r.currency)}</span> : null}
                </div>
                <ChevronRight className="h-4 w-4 text-muted-foreground" />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}