"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { apiGet, apiPost, apiPut } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { useToast } from "@/hooks/use-toast";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { LoadingState, ErrorState, EmptyState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import {
  ArrowLeft, FileText, MapPin, Calendar, Heart, Trophy, Send, CheckCircle2, XCircle,
  RotateCcw, Upload, Lock, Star, Receipt, ScrollText, ShieldCheck, Clock, AlertTriangle, Download,
  Users, Package, ThumbsUp, ThumbsDown, AlertCircle, Info, Link2,
} from "lucide-react";
import { formatDate, formatDateTime, formatMoney, formatUSD, evaluateDeadline } from "@/lib/constants";

export function RequestDetail() {
  const { params, navigate, user } = useAppStore();
  const { toast } = useToast();
  const [request, setRequest] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState("overview");
  const [actionLoading, setActionLoading] = useState(false);

  // Thêm ref để xử lý upload file thật
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadingDocContext, setUploadingDocContext] = useState<{ docType: string, horseId: string } | null>(null);

  // Options & quote state
  const [optionsData, setOptionsData] = useState<any>(null);
  const [selectedOption, setSelectedOption] = useState<string>("");
  const [selectedStall, setSelectedStall] = useState<string>(""); 
  const [selectedStallName, setSelectedStallName] = useState<string>("");
  const [rideShareEnabled, setRideShareEnabled] = useState<boolean>(false);
  const [selectedAddOns, setSelectedAddOns] = useState<Record<string, { id: string; name: string; unitPrice: number; quantity: number; unit: string }>>({});
  const [savedTotal, setSavedTotal] = useState<number | null>(null);
  const [hasConfirmedOptions, setHasConfirmedOptions] = useState(false);

  // Review/approval state
  const [reviewNote, setReviewNote] = useState("");
  const [approvalNote, setApprovalNote] = useState("");

  // Documents state
  const [docsData, setDocsData] = useState<any>(null);
  const [compliance, setCompliance] = useState<any>(null);
  const [history, setHistory] = useState<any[]>([]);

  const load = useCallback(async () => {
    try {
      // 1. Chuẩn hóa lại đường dẫn API
      const [reqData, histData] = await Promise.all([
        apiGet(`/api/transport-requests/${params.id}`),
        apiGet(`/api/transport-requests/${params.id}/history`).catch(() => ({ history: [] })), // Dự phòng nếu Backend chưa có lịch sử
      ]);
      
      const req = reqData.request || reqData;
      setRequest(req);
      
      setHasConfirmedOptions(
        Boolean(
          req.selectedOptionId ||
          req.optionSelections?.some((selection: any) => selection.isSelected)
        )
      );
      setSavedTotal(req.estimatedAmount ?? null);
      setHistory(Array.isArray(histData) ? histData : histData.history || []);
    } catch (e: any) { 
      setError(e.message || "Lỗi khi tải chi tiết đơn hàng."); 
    }
    finally { setLoading(false); }
  }, [params.id]);

  useEffect(() => { load(); }, [load]);

  const loadOptions = useCallback(async () => {
    try {
      const d = await apiGet(`/api/transport-requests/${params.id}/options`);
      setOptionsData(d);
      const selected = d.selectedSelection || request?.optionSelections?.find((s: any) => s.isSelected);
      if (selected) {
        setHasConfirmedOptions(true);
        setSelectedOption(selected.optionId);
        setSelectedStall(selected.stallConfigId || "");
        setSelectedStallName(selected.stallConfig || "");
        setRideShareEnabled(selected.rideShareEnabled || false);
        try {
          const savedAddOns = selected.addOns ? (typeof selected.addOns === 'string' ? JSON.parse(selected.addOns) : selected.addOns) : [];
          setSelectedAddOns(
            Array.isArray(savedAddOns)
              ? Object.fromEntries(savedAddOns.map((addOn: any) => [addOn.id, addOn]))
              : {}
          );
        } catch {
          setSelectedAddOns({});
        }
      } else if (d.options?.[0]) {
        const best = d.options[0];
        setSelectedOption(best.option.optionId || best.option.id);
        if (best.bestStallConfigId) {
          setSelectedStall(best.bestStallConfigId);
          const sc = best.stallConfigs?.find((s: any) => s.configId === best.bestStallConfigId);
          setSelectedStallName(sc?.name || "");
        }
      }
      if (request?.estimatedAmount != null) setSavedTotal(request.estimatedAmount);
    } catch { /* options may not be available yet */ }
  }, [params.id, request]);

  const loadDocs = useCallback(async () => {
    try {
      const [docs, comp] = await Promise.all([
        apiGet(`/api/transport-requests/${params.id}/documents`).catch(() => null),
        apiGet(`/api/transport-requests/${params.id}/compliance`).catch(() => null),
      ]);
      setDocsData(docs);
      setCompliance(comp);
    } catch { /* ignore */ }
  }, [params.id]);

  useEffect(() => {
    if (activeTab === "options" && !optionsData) loadOptions();
    if (activeTab === "documents" && !docsData) loadDocs();
    if (activeTab === "compliance" && !compliance) loadDocs();
  }, [activeTab, loadOptions, loadDocs, optionsData, docsData, compliance]);

  const handleSaveOption = async () => {
    if (!selectedOption) { toast({ title: "Chưa chọn phương án", variant: "destructive" }); return; }
    if (!selectedStall) { toast({ title: "Chưa chọn cấu hình chuồng", variant: "destructive" }); return; }
    setActionLoading(true);
    try {
      const addOnArray = Object.values(selectedAddOns);
      const data = await apiPost(`/api/transport-requests/${params.id}/options`, {
        optionId: selectedOption,
        stallConfigId: selectedStall,
        rideShareEnabled,
        addOns: addOnArray.length > 0 ? addOnArray : undefined,
      });
      setSavedTotal(data.total);
      setHasConfirmedOptions(true);
      
      toast({ title: "Đã lưu lựa chọn", description: `Tổng dự kiến: ${formatMoney(data.total, "USD")}` });
      load();
    } catch (e: any) {
      toast({ title: "Lỗi lưu phương án", description: e.message, variant: "destructive" });
    }
    finally { setActionLoading(false); }
  };

  const handleSubmit = async () => {
    setActionLoading(true);
    try {
      // Flow: Submit for Review
      await apiPost(`/api/transport-requests/${params.id}/submit`);
      toast({ title: "Đã gửi đơn", description: "Đơn vận chuyển đã được gửi đi thẩm định." });
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setActionLoading(false); }
  };

  const handleReview = async (decision: string) => {
    setActionLoading(true);
    try {
      // Giả sử API duyệt của bạn là PUT hoặc POST tuỳ vào Spring Boot
      await apiPut(`/api/transport-requests/${params.id}/${decision === 'approve' ? 'approve' : 'reject'}`, { note: reviewNote });
      toast({ title: "Thành công", description: "Đã ghi nhận kết quả thẩm định." });
      setReviewNote("");
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setActionLoading(false); }
  };

  const handleApproval = async (decision: string) => {
    setActionLoading(true);
    try {
      await apiPut(`/api/transport-requests/${params.id}/${decision === 'approve' ? 'approve' : 'reject'}`, { note: approvalNote });
      toast({ title: decision === "approve" ? "Đã phê duyệt đơn" : "Đã từ chối đơn" });
      setApprovalNote("");
      load();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setActionLoading(false); }
  };

  // 2. Hàm kích hoạt input file thật
  const triggerFileUpload = (docType: string, horseId: string) => {
    setUploadingDocContext({ docType, horseId });
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  // 3. Hàm xử lý upload thực tế khi người dùng chọn file
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0 || !uploadingDocContext) return;
    
    const file = e.target.files[0];
    setActionLoading(true);
    
    try {
      // TODO: Thay bằng API Upload File thật sự của Backend
      // Tạo FormData nếu Backend yêu cầu Multipart File
      const formData = new FormData();
      formData.append("file", file);
      formData.append("documentType", uploadingDocContext.docType);
      
      // Giả lập API gọi lên server
      await apiPost(`/api/horses/${uploadingDocContext.horseId}/documents`, {
         documentType: uploadingDocContext.docType,
         fileName: file.name,
         fileUrl: "dummy_url_for_now"
      });
      
      toast({ title: "Đã nộp tài liệu", description: file.name });
      loadDocs();
    } catch (err: any) {
      toast({ title: "Lỗi tải lên", description: err.message, variant: "destructive" });
    } finally {
      setActionLoading(false);
      setUploadingDocContext(null);
      if (fileInputRef.current) fileInputRef.current.value = ""; // Reset input
    }
  };

  const handleReviewDoc = async (docId: string, status: string) => {
    const note = status === "Cần bổ sung" ? prompt("Lý do yêu cầu bổ sung:") : "";
    if (status === "Cần bổ sung" && note === null) return; // User cancelled
    
    setActionLoading(true);
    try {
      await apiPut(`/api/documents/${docId}/review`, { status, reviewNote: note });
      toast({ title: `Đã cập nhật: ${status}` });
      loadDocs();
    } catch (e: any) { toast({ title: "Lỗi", description: e.message, variant: "destructive" }); }
    finally { setActionLoading(false); }
  };

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;
  if (!request) return <ErrorState message="Không tìm thấy đơn" />;

  // Logic phân quyền theo Role của hệ thống
  const reqStatus = (request.status || "").toUpperCase();
  const userRole = user?.roleId || "";
  
  const canEdit = userRole === "CUSTOMER" && ["DRAFT", "PENDING", "NHÁP", "CHỜ DUYỆT"].includes(reqStatus);
  const canViewOptions = ["CUSTOMER", "LOGISTICS_MANAGER"].includes(userRole);
  const canEditOptions = canEdit && !hasConfirmedOptions;
  const selectedTab = activeTab === "options" && !canViewOptions ? "overview" : activeTab;
  const canSubmit = canEdit;
  const canReview = userRole === "TRANSPORT_SPECIALIST" && ["PENDING", "UNDER_REVIEW"].includes(reqStatus);
  const canApprove = userRole === "LOGISTICS_MANAGER" && ["PENDING", "UNDER_REVIEW"].includes(reqStatus);
  const isSpecialist = userRole === "TRANSPORT_SPECIALIST";
  const isCustomer = userRole === "CUSTOMER";

  // Real-time price calculation for the price summary table
  const currentOption = optionsData?.options?.find((o: any) => (o.option.optionId || o.option.id) === selectedOption);
  const currentStallConfig = currentOption?.stallConfigs?.find((s: any) => s.configId === selectedStall);
  const totalHorses = request.horses?.length || request.horseIds?.length || 0;
  const isInternationalRoute = request.originLocation?.countryCode !== request.destinationLocation?.countryCode;

  const calcBaseCost = currentOption ? Math.round((currentOption.option.baseCost || 0) * totalHorses * 100) / 100 : 0;
  const calcStallUnitPrice = currentOption && currentStallConfig ? Math.round((currentOption.option.baseCost || 0) * (currentStallConfig.priceMultiplierPerHorse || 1) * 100) / 100 : 0;
  const calcStallCost = Math.round(calcStallUnitPrice * totalHorses * 100) / 100;
  const calcMandatoryDocs = isInternationalRoute ? 350 : 0;
  const calcQuarantine = isInternationalRoute ? 500 : 0;
  const calcAddOnTotal = Math.round(Object.values(selectedAddOns).reduce((s: number, a: any) => s + a.unitPrice * a.quantity, 0) * 100) / 100;
  const calcTotal = Math.round((calcBaseCost + calcStallCost + calcMandatoryDocs + calcQuarantine + calcAddOnTotal) * 100) / 100;

  return (
    <div className="space-y-6">
      {/* Input File ẩn dùng chung */}
      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
      
      <PageHeader
        title={request.competitionName || `Đơn #${String(request.id || request.requestId || "").slice(-8).toUpperCase()}`}
        description={`Mã: ${String(request.id || request.requestId || "").slice(-12).toUpperCase()}`}
        icon={<FileText className="h-5 w-5" />}
        actions={
          <div className="flex items-center gap-2">
            <StatusBadge status={request.status} />
            <Button variant="outline" size="sm" onClick={() => navigate("requests")} className="gap-2"><ArrowLeft className="h-4 w-4" /> Quay lại</Button>
          </div>
        }
      />

      {/* Info cards */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Khách hàng</p><p className="mt-1 text-sm font-semibold">{request.customer?.name || user?.name || "Chưa rõ"}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Tuyến</p><p className="mt-1 text-sm font-semibold leading-tight">{request.originLocation?.name || request.origin?.name || "..."}</p><p className="text-xs text-muted-foreground">→ {request.destinationLocation?.name || request.destination?.name || "..."}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Khởi hành</p><p className="mt-1 text-sm font-semibold">{formatDate(request.scheduledDepartureDate)}</p><p className="text-xs text-muted-foreground">Đến dự kiến: {formatDate(request.scheduledArrivalDate)}</p></CardContent></Card>
        <Card><CardContent className="p-4"><p className="text-xs text-muted-foreground">Tổng dự kiến</p><p className="mt-1 text-lg font-bold text-primary">{request.estimatedAmount ? formatMoney(request.estimatedAmount, request.currency || "USD") : "Chưa chốt"}</p></CardContent></Card>
      </div>

      <Tabs value={selectedTab} onValueChange={(tab) => {
        if (tab !== "options" || canViewOptions) setActiveTab(tab);
      }}>
        <TabsList className="flex w-full flex-wrap justify-start gap-1 h-auto p-1">
          <TabsTrigger value="overview" className="gap-1.5"><FileText className="h-4 w-4" /> Tổng quan</TabsTrigger>
          {canViewOptions && <TabsTrigger value="options" className="gap-1.5"><Star className="h-4 w-4" /> Báo giá</TabsTrigger>}
          <TabsTrigger value="documents" className="gap-1.5"><ScrollText className="h-4 w-4" /> Giấy tờ</TabsTrigger>
          <TabsTrigger value="compliance" className="gap-1.5"><ShieldCheck className="h-4 w-4" /> Kiểm dịch</TabsTrigger>
          <TabsTrigger value="history" className="gap-1.5"><Clock className="h-4 w-4" /> Lịch sử</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-4">
          <div className="grid gap-6 lg:grid-cols-2">
            <Card>
              <CardHeader><CardTitle className="text-base flex items-center gap-2"><Heart className="h-4 w-4" /> Ngựa vận chuyển ({totalHorses} con)</CardTitle></CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {request.horses?.map((rh: any, idx: number) => {
                    const horse = rh.horse || rh; // Tùy thuộc cấu trúc Backend
                    const hId = horse.id || horse.horseId;
                    return (
                      <button key={hId || idx} onClick={() => navigate("horse-detail", { id: hId })} className="flex w-full items-center justify-between rounded-lg border border-border p-3 text-left hover:border-primary/40">
                        <div><p className="text-sm font-medium">{horse.name}</p><p className="text-xs text-muted-foreground">{horse.microchipId || "Không mã"} · {horse.gender || "Không rõ"}</p></div>
                        <Badge variant="outline">{horse.breed || "Thoroughbred"}</Badge>
                      </button>
                    )
                  })}
                </div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader><CardTitle className="text-base flex items-center gap-2"><Trophy className="h-4 w-4" /> Thông tin đơn</CardTitle></CardHeader>
              <CardContent className="space-y-3 text-sm">
                <div className="flex justify-between"><span className="text-muted-foreground">Tên giải đấu</span><span className="font-medium">{request.competitionName || "—"}</span></div>
                <div className="flex justify-between"><span className="text-muted-foreground">Deadline có mặt</span><span className="font-medium">{request.deadlineDateTime ? formatDateTime(request.deadlineDateTime) : "—"}</span></div>
                <div className="flex justify-between"><span className="text-muted-foreground">Múi giờ</span><span className="font-medium">{request.deadlineTimezone || "Asia/Ho_Chi_Minh"}</span></div>
                {request.specialRequirements && <div className="border-t border-border pt-3"><p className="text-muted-foreground">Yêu cầu đặc biệt</p><p className="mt-1 font-medium">{request.specialRequirements}</p></div>}
              </CardContent>
            </Card>
          </div>

          {/* Action bar (Submit/Approve) */}
          {canSubmit && (
            <Card className="border-primary/30 bg-primary/5">
              <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between">
                <div><p className="text-sm font-semibold">Sẵn sàng gửi đơn?</p><p className="text-xs text-muted-foreground">Đơn sẽ được gửi cho Quản lý phê duyệt.</p></div>
                <Button onClick={handleSubmit} disabled={actionLoading} className="gap-2"><Send className="h-4 w-4" /> Gửi Yêu Cầu</Button>
              </CardContent>
            </Card>
          )}

          {canApprove && (
            <Card className="border-[var(--warning)]/30 bg-[var(--warning-bg)]/20">
              <CardHeader><CardTitle className="text-base">Duyệt Yêu Cầu Vận Chuyển</CardTitle></CardHeader>
              <CardContent className="space-y-3">
                <div className="space-y-2"><Label>Ghi chú của Quản lý (Bắt buộc)</Label><Textarea value={approvalNote} onChange={(e) => setApprovalNote(e.target.value)} placeholder="Lý do phê duyệt hoặc từ chối..." rows={2} /></div>
                <div className="flex flex-wrap gap-2 pt-2">
                  <Button onClick={() => handleApproval("approve")} disabled={actionLoading || !approvalNote.trim()} className="gap-2 bg-[var(--success)] hover:bg-[var(--success)]/90 text-white"><CheckCircle2 className="h-4 w-4" /> Phê duyệt đơn</Button>
                  <Button onClick={() => handleApproval("reject")} disabled={actionLoading || !approvalNote.trim()} variant="outline" className="gap-2 border-[var(--danger)] text-[var(--danger-fg)]"><XCircle className="h-4 w-4" /> Từ chối</Button>
                </div>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* ... (Các phần TabsContent "options", "documents", "compliance", "history" giữ nguyên logic như bản gốc của bạn, 
             chỉ lưu ý đổi handleUploadDoc thành gọi `triggerFileUpload(docType, horseId)`) */}
             
        {/* Ví dụ sửa phần nút Nộp tài liệu trong tab Documents */}
        <TabsContent value="documents" className="space-y-4">
          {!docsData ? <p className="text-sm text-muted-foreground mt-4">API Tài liệu chưa sẵn sàng.</p> : (
            <Card>
              <CardHeader><CardTitle className="text-base flex items-center gap-2"><ScrollText className="h-4 w-4" /> Checklist giấy tờ</CardTitle></CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {/* ... map danh sách tài liệu */}
                  {/* Nút Upload được sửa lại: */}
                  {canEdit && request.horses?.[0] && (
                     <Button size="sm" variant="outline" onClick={() => triggerFileUpload("PASSPORT", request.horses[0].id || request.horses[0].horseId)} className="gap-1 mt-4"><Upload className="h-3.5 w-3.5" /> Nộp thêm tài liệu</Button>
                  )}
                </div>
              </CardContent>
            </Card>
          )}
        </TabsContent>

      </Tabs>
    </div>
  );
}